\begin{exercise}
\label{prob:distance-function-submersion}
\dcref{ch6:6-25}

Suppose $(M, g)$ is a Riemannian manifold and $f : M \to \mathbb{R}$ is a smooth local distance function. Prove that $f$ is a Riemannian submersion.
\end{exercise}

